content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #eef2ff;
  --success-color: #10b981;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --bg-gradient: linear-gradient(135deg, #f0f4ff 0%, #e8edf7 100%);
  --card-bg: #ffffff;
  --border-color: #e2e8f0;
  --border-focus: #818cf8;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 25px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Sans", "Noto Sans JP", sans-serif;
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 32px 16px;
  -webkit-font-smoothing: antialiased;
}

/* アプリ全体のラッパーコンテナ */
.todo-app {
  width: 100%;
  max-width: 640px;
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  border: 1px solid rgba(255, 255, 255, 0.8);
}

/* ヘッダーエリア */
.app-header {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* 統計バッジエリア */
.stats-container {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 8px 0;
}

.stat-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background-color: #f8fafc;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-muted);
}

.stat-badge strong {
  color: var(--primary-color);
  font-size: 0.95rem;
}

/* タスク入力フォーム */
.todo-form {
  width: 100%;
}

.input-group {
  display: flex;
  gap: 8px;
}

.todo-input {
  flex: 1;
  padding: 12px 16px;
  font-size: 1rem;
  border: 2px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background-color: #fff;
  color: var(--text-main);
  transition: var(--transition);
}

.todo-input::placeholder {
  color: var(--text-light);
}

.todo-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.15);
}

.add-button {
  padding: 12px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--primary-color);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.add-button:hover {
  background-color: var(--primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.add-button:active {
  transform: translateY(0);
}

/* フィルタータブ切り替え */
.filter-tabs {
  display: flex;
  background-color: #f1f5f9;
  padding: 4px;
  border-radius: var(--radius-md);
  gap: 4px;
}

.filter-button {
  flex: 1;
  padding: 8px 12px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  text-align: center;
}

.filter-button:hover {
  color: var(--text-main);
}

.filter-button-active {
  background-color: #ffffff;
  color: var(--primary-color);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* タスク一覧リスト */
.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0;
  padding: 0;
}

/* 単一タスク項目 */
.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  gap: 12px;
}

.todo-item:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.todo-item-completed {
  background-color: #f8fafc;
  border-color: #e2e8f0;
}

.todo-item-completed .todo-text {
  text-decoration: line-through;
  color: var(--text-light);
}

/* チェックボックス・ラベル */
.checkbox-label {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  cursor: pointer;
  user-select: none;
  min-width: 0;
}

.custom-checkbox {
  width: 20px;
  height: 20px;
  min-width: 20px;
  cursor: pointer;
  accent-color: var(--primary-color);
}

.todo-text {
  font-size: 0.95rem;
  color: var(--text-main);
  word-break: break-word;
  transition: var(--transition);
  line-height: 1.4;
}

.todo-date {
  font-size: 0.75rem;
  color: var(--text-light);
  white-space: nowrap;
  margin-left: auto;
  padding-left: 8px;
}

/* 削除ボタン */
.delete-button {
  background: transparent;
  color: var(--text-light);
  border: none;
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  font-size: 0.85rem;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.delete-button:hover {
  background-color: var(--danger-light);
  color: var(--danger-color);
}

.delete-button:active {
  background-color: #fee2e2;
}

/* 空状態の表示 */
.empty-state {
  text-align: center;
  padding: 40px 16px;
  color: var(--text-muted);
  font-size: 0.95rem;
  background-color: #f8fafc;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
}

/* フッターサマリー */
.footer-summary {
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border-color);
  padding-top: 16px;
}

/* レスポンシブ対応 (360px以下の小型画面など) */
@media (max-width: 480px) {
  body {
    padding: 16px 8px;
  }

  .todo-app {
    padding: 20px 16px;
    gap: 16px;
  }

  .app-title {
    font-size: 1.4rem;
  }

  .input-group {
    flex-direction: column;
  }

  .add-button {
    width: 100%;
    padding: 10px;
  }

  .todo-item {
    padding: 10px 12px;
  }

  .todo-date {
    display: none;
  }
}

export interface TodoItemType {
  id: string;
  text: string;
  completed: boolean;
  createdAt: string;
}

export type FilterType = 'all' | 'active' | 'completed';

export interface TodoInputProps {
  onAddTodo: (text: string) => void;
}

export interface TodoItemProps {
  todo: TodoItemType;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

import { useState, type FormEvent } from 'react';
import { TodoInputProps } from '../types';

const TodoInput = ({ onAddTodo }: TodoInputProps) => {
  const [inputText, setInputText] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = inputText.trim();
    if (!trimmed) {
      return;
    }
    onAddTodo?.(trimmed);
    setInputText('');
  };

  return (
    <form className="todo-form" onSubmit={handleSubmit}>
      <div className="input-group">
        <input
          type="text"
          className="todo-input"
          placeholder="新しいタスクを入力してください..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button type="submit" className="add-button">
          タスクを追加
        </button>
      </div>
    </form>
  );
};

export default TodoInput;

import { TodoItemProps } from '../types';

const TodoItem = ({ todo, onToggle, onDelete }: TodoItemProps) => {
  const itemClassName = todo.completed ? 'todo-item todo-item-completed' : 'todo-item';

  const handleCheckboxChange = () => {
    onToggle?.(todo.id);
  };

  const handleDelete = () => {
    onDelete?.(todo.id);
  };

  return (
    <li className={itemClassName}>
      <label className="checkbox-label">
        <input
          type="checkbox"
          className="custom-checkbox"
          checked={todo.completed}
          onChange={handleCheckboxChange}
        />
        <span className="todo-text">{todo.text}</span>
      </label>
      <span className="todo-date">{todo.createdAt}</span>
      <button
        type="button"
        className="delete-button"
        onClick={handleDelete}
        title="タスクを削除"
        aria-label={`${todo.text}を削除`}
      >
        削除
      </button>
    </li>
  );
};

export default TodoItem;

import { useState, useMemo } from 'react';
import { TodoItemType, FilterType } from './types';
import TodoInput from './components/TodoInput';
import TodoItem from './components/TodoItem';
import './index.css';

const INITIAL_TODOS: TodoItemType[] = [
  {
    id: '1',
    text: '牛乳を買う',
    completed: false,
    createdAt: '今日 09:30',
  },
  {
    id: '2',
    text: '報告書を作成する',
    completed: false,
    createdAt: '今日 10:15',
  },
  {
    id: '3',
    text: '部屋の掃除をする',
    completed: true,
    createdAt: '昨日 18:00',
  },
  {
    id: '4',
    text: '散歩をする',
    completed: false,
    createdAt: '今日 07:00',
  },
  {
    id: '5',
    text: 'メールに返信する',
    completed: true,
    createdAt: '昨日 16:45',
  },
];

const App = () => {
  const [todos, setTodos] = useState<TodoItemType[]>(INITIAL_TODOS);
  const [filter, setFilter] = useState<FilterType>('all');

  const handleAddTodo = (text: string) => {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const newTodo: TodoItemType = {
      id: String(Date.now()),
      text,
      completed: false,
      createdAt: `今日 ${hours}:${minutes}`,
    };
    setTodos((prev) => [newTodo, ...prev]);
  };

  const handleToggle = (id: string) => {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDelete = (id: string) => {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  };

  const filteredTodos = useMemo(() => {
    switch (filter) {
      case 'active':
        return todos.filter((todo) => !todo.completed);
      case 'completed':
        return todos.filter((todo) => todo.completed);
      case 'all':
      default:
        return todos;
    }
  }, [todos, filter]);

  const totalCount = todos.length;
  const completedCount = todos.filter((todo) => todo.completed).length;
  const activeCount = totalCount - completedCount;

  const allButtonClassName =
    filter === 'all' ? 'filter-button filter-button-active' : 'filter-button';
  const activeButtonClassName =
    filter === 'active' ? 'filter-button filter-button-active' : 'filter-button';
  const completedButtonClassName =
    filter === 'completed' ? 'filter-button filter-button-active' : 'filter-button';

  return (
    <div className="todo-app">
      <header className="app-header">
        <h1 className="app-title">やることリスト</h1>
        <p className="app-subtitle">今日のタスクを整理して、充実した一日にしましょう</p>
      </header>

      <section className="stats-container">
        <span className="stat-badge">
          全タスク: <strong>{totalCount}</strong> 件
        </span>
        <span className="stat-badge">
          未完了: <strong>{activeCount}</strong> 件
        </span>
        <span className="stat-badge">
          完了済み: <strong>{completedCount}</strong> 件
        </span>
      </section>

      <TodoInput onAddTodo={handleAddTodo} />

      <nav className="filter-tabs" aria-label="タスク絞り込み">
        <button
          type="button"
          className={allButtonClassName}
          onClick={() => setFilter('all')}
        >
          すべて ({totalCount})
        </button>
        <button
          type="button"
          className={activeButtonClassName}
          onClick={() => setFilter('active')}
        >
          未完了 ({activeCount})
        </button>
        <button
          type="button"
          className={completedButtonClassName}
          onClick={() => setFilter('completed')}
        >
          完了済み ({completedCount})
        </button>
      </nav>

      {filteredTodos.length === 0 ? (
        <div className="empty-state">
          {filter === 'completed' && '完了済みのタスクはありません。'}
          {filter === 'active' && 'すべてのタスクが完了しています！'}
          {filter === 'all' && 'タスクが登録されていません。新しいタスクを追加しましょう！'}
        </div>
      ) : (
        <ul className="todo-list">
          {filteredTodos.map((todo) => (
            <TodoItem
              key={todo.id}
              todo={todo}
              onToggle={handleToggle}
              onDelete={handleDelete}
            />
          ))}
        </ul>
      )}

      <footer className="footer-summary">
        {totalCount > 0 ? (
          <span>
            {activeCount === 0
              ? 'すべてのタスクを達成しました！素晴らしい成果です。'
              : `残り ${activeCount} 件のやることがあります。`}
          </span>
        ) : (
          <span>タスクを追加して作業を始めましょう。</span>
        )}
      </footer>
    </div>
  );
};

export default App;
